//! BitTorrent transport.
//!
//! Torrents are generated by servers and are **not signed**, so nothing here
//! is trusted:
//!
//! * A torrent is only used if its file list is exactly the file list of the
//!   signed release manifest ([`check_metainfo`]).
//! * Downloads go to a scratch directory. Chunks are then lifted out of it
//!   one by one, each verified against the manifest's BLAKE3 IDs, exactly
//!   like chunks from HTTP. Whatever the swarm did not deliver (or delivered
//!   wrong) is fetched over HTTP.
//! * An install directory is only seeded after its piece hashes were
//!   recomputed locally and match the torrent ([`tree_pieces`]), so the
//!   torrent client finds it complete and never writes into it.

use crate::{Error, Result};
use gamedist_core::{
    manifest::Platform,
    paths,
    torrent::{Bencode, PieceHasher},
};
use sha1::{Digest, Sha1};
use std::{io::Read, path::Path};

/// Largest torrent file accepted from a server.
pub const MAX_METAINFO_SIZE: usize = 32 * 1024 * 1024;

/// The parts of a validated torrent the launcher needs.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TorrentCheck {
    pub info_hash: [u8; 20],
    pub piece_length: u32,
    /// Concatenated SHA-1 piece hashes.
    pub pieces: Vec<u8>,
}

impl TorrentCheck {
    pub fn info_hash_hex(&self) -> String {
        data_encoding_hex(&self.info_hash)
    }
}

fn data_encoding_hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

/// Check that untrusted metainfo describes exactly `platform`'s install tree:
/// a multi-file v1 torrent named `files` whose files are the manifest's files
/// in order, with the same sizes, and nothing else in the info dictionary.
pub fn check_metainfo(bytes: &[u8], platform: &Platform) -> Result<TorrentCheck> {
    let bad = |why: &str| Error::msg(format!("server sent an unusable torrent: {why}"));
    if bytes.len() > MAX_METAINFO_SIZE {
        return Err(bad("too large"));
    }
    let root = Bencode::decode(bytes).map_err(|e| bad(&e.to_string()))?;
    let info = root.get("info").ok_or_else(|| bad("no info dictionary"))?;
    let Bencode::Dict(info_map) = info else {
        return Err(bad("info is not a dictionary"));
    };
    let allowed: [&[u8]; 4] = [b"files", b"name", b"piece length", b"pieces"];
    if info_map.len() != 4 || !info_map.keys().all(|k| allowed.contains(&k.as_slice())) {
        return Err(bad("unexpected members in the info dictionary"));
    }
    if info.get("name").and_then(Bencode::as_bytes) != Some(b"files") {
        return Err(bad("unexpected name"));
    }
    let piece_length = info
        .get("piece length")
        .and_then(Bencode::as_int)
        .filter(|l| (16 * 1024..=64 * 1024 * 1024).contains(l))
        .ok_or_else(|| bad("bad piece length"))? as u32;
    let Some(Bencode::List(files)) = info.get("files") else {
        return Err(bad("not a multi-file torrent"));
    };
    if files.len() != platform.files.len() {
        return Err(bad("file list does not match the signed manifest"));
    }
    for (torrent_file, manifest_file) in files.iter().zip(&platform.files) {
        let length = torrent_file.get("length").and_then(Bencode::as_int);
        let path = match torrent_file.get("path") {
            Some(Bencode::List(parts)) => parts
                .iter()
                .map(|p| p.as_bytes().and_then(|b| std::str::from_utf8(b).ok()))
                .collect::<Option<Vec<&str>>>()
                .map(|parts| parts.join("/")),
            _ => None,
        };
        let Bencode::Dict(file_map) = torrent_file else {
            return Err(bad("malformed file entry"));
        };
        if file_map.len() != 2
            || length != Some(manifest_file.size as i64)
            || path.as_deref() != Some(manifest_file.path.as_str())
        {
            return Err(bad("file list does not match the signed manifest"));
        }
    }
    let pieces = info
        .get("pieces")
        .and_then(Bencode::as_bytes)
        .ok_or_else(|| bad("no piece hashes"))?;
    let expected = platform.total_size.div_ceil(piece_length as u64) as usize * 20;
    if pieces.len() != expected {
        return Err(bad("wrong number of piece hashes"));
    }
    Ok(TorrentCheck {
        info_hash: Sha1::digest(info.encode()).into(),
        piece_length,
        pieces: pieces.to_vec(),
    })
}

/// SHA-1 piece hashes of an installed tree, files concatenated in manifest
/// order. Symlinks are refused.
pub fn tree_pieces(platform: &Platform, dir: &Path, piece_length: u32) -> Result<Vec<u8>> {
    let mut hasher = PieceHasher::new(piece_length);
    let mut buf = vec![0u8; 1024 * 1024];
    for file in &platform.files {
        let path = paths::join_no_symlinks(dir, &file.path)?;
        let err = |e: std::io::Error| Error::msg(format!("reading {}: {e}", path.display()));
        let mut handle = std::fs::File::open(&path).map_err(err)?;
        let mut remaining = file.size;
        while remaining > 0 {
            let want = remaining.min(buf.len() as u64) as usize;
            handle.read_exact(&mut buf[..want]).map_err(err)?;
            hasher.update(&buf[..want]);
            remaining -= want as u64;
        }
    }
    Ok(hasher.finish())
}

#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct SeedStatus {
    pub game_id: String,
    pub info_hash: String,
    pub uploaded_bytes: u64,
    pub total_bytes: u64,
}

#[cfg(feature = "torrent")]
pub use engine::{EngineOptions, TorrentEngine};

/// Engine options derived from the launcher settings.
#[cfg(feature = "torrent")]
pub fn engine_options(scratch: std::path::PathBuf, settings: &crate::Settings) -> EngineOptions {
    EngineOptions {
        scratch,
        listen_port: settings.listen_port,
        download_limit: settings.bandwidth_limit,
        // Not seeding means not uploading to the swarm beyond tit-for-tat
        // during a download; an explicit limit still applies.
        upload_limit: settings.upload_limit,
    }
}

#[cfg(feature = "torrent")]
mod engine {
    use super::*;
    use librqbit::{
        api::TorrentIdOrHash, limits::LimitsConfig, AddTorrent, AddTorrentOptions, ListenerMode,
        ListenerOptions, ManagedTorrent, Session, SessionOptions,
    };
    use std::{
        collections::HashMap,
        net::{Ipv4Addr, SocketAddr},
        num::NonZeroU32,
        path::PathBuf,
        sync::{Arc, Mutex},
        time::{Duration, Instant},
    };

    type ManagedTorrentHandle = Arc<ManagedTorrent>;

    fn rq(e: impl std::fmt::Display) -> Error {
        Error::msg(format!("torrent: {e}"))
    }

    pub struct EngineOptions {
        pub scratch: PathBuf,
        /// 0 picks a free port.
        pub listen_port: u16,
        pub download_limit: Option<u64>,
        pub upload_limit: Option<u64>,
    }

    /// One BitTorrent session per launcher process. DHT and local service
    /// discovery are off: peers come from the trackers named in the torrent.
    pub struct TorrentEngine {
        session: Arc<Session>,
        seeds: Mutex<HashMap<String, (ManagedTorrentHandle, String)>>,
    }

    impl TorrentEngine {
        pub async fn start(opts: EngineOptions) -> Result<Self> {
            std::fs::create_dir_all(&opts.scratch)
                .map_err(|e| Error::msg(format!("creating {}: {e}", opts.scratch.display())))?;
            let bps = |limit: Option<u64>| {
                limit
                    .filter(|l| *l > 0)
                    .and_then(|l| NonZeroU32::new(l.min(u32::MAX as u64) as u32))
            };
            let session = Session::new_with_opts(
                opts.scratch.clone(),
                SessionOptions {
                    dht: None,
                    disable_local_service_discovery: true,
                    persistence: None,
                    listen: Some(ListenerOptions {
                        mode: ListenerMode::TcpOnly,
                        listen_addr: SocketAddr::new(
                            Ipv4Addr::UNSPECIFIED.into(),
                            opts.listen_port,
                        ),
                        enable_upnp_port_forwarding: false,
                        ..Default::default()
                    }),
                    ratelimits: LimitsConfig {
                        upload_bps: bps(opts.upload_limit),
                        download_bps: bps(opts.download_limit),
                    },
                    client_name_and_version: Some(format!(
                        "gamedist {}",
                        env!("CARGO_PKG_VERSION")
                    )),
                    ..Default::default()
                },
            )
            .await
            .map_err(rq)?;
            Ok(TorrentEngine {
                session,
                seeds: Mutex::new(HashMap::new()),
            })
        }

        pub fn listen_port(&self) -> Option<u16> {
            self.session.listen_addr().map(|a| a.port())
        }

        /// Download (a subset of) a torrent into `dest`. Returns when it is
        /// complete or when no progress was made for `stall`. The data in
        /// `dest` is unverified; the caller lifts verified chunks out of it.
        /// Returns the number of bytes the torrent client considers done.
        pub async fn download(
            &self,
            metainfo: Vec<u8>,
            dest: &Path,
            only_files: Vec<usize>,
            stall: Duration,
            on_progress: impl Fn(u64, u64),
        ) -> Result<u64> {
            let handle = self
                .session
                .add_torrent(
                    AddTorrent::from_bytes(metainfo),
                    Some(AddTorrentOptions {
                        overwrite: true,
                        output_folder: Some(dest.display().to_string()),
                        only_files: Some(only_files),
                        ..Default::default()
                    }),
                )
                .await
                .map_err(rq)?
                .into_handle()
                .ok_or_else(|| Error::msg("torrent: could not add torrent"))?;

            let mut last_progress = 0u64;
            let mut last_change = Instant::now();
            let done = loop {
                tokio::time::sleep(Duration::from_millis(100)).await;
                let stats = handle.stats();
                on_progress(stats.progress_bytes, stats.total_bytes);
                if stats.finished || stats.error.is_some() {
                    break stats.progress_bytes;
                }
                if stats.progress_bytes != last_progress {
                    last_progress = stats.progress_bytes;
                    last_change = Instant::now();
                } else if last_change.elapsed() >= stall {
                    break stats.progress_bytes;
                }
            };
            // Stop it; files stay for the caller to harvest.
            let _ = self
                .session
                .delete(TorrentIdOrHash::Id(handle.id()), false)
                .await;
            Ok(done)
        }

        /// Seed `dir` for `game_id`. The caller has already established that
        /// the directory's content matches the torrent's piece hashes; if the
        /// torrent client disagrees, seeding is refused rather than letting
        /// it "repair" an install directory with unsigned data.
        pub async fn seed(
            &self,
            game_id: &str,
            metainfo: Vec<u8>,
            dir: &Path,
            info_hash: &str,
        ) -> Result<()> {
            self.stop(game_id).await;
            let handle = self
                .session
                .add_torrent(
                    AddTorrent::from_bytes(metainfo),
                    Some(AddTorrentOptions {
                        paused: true,
                        overwrite: true,
                        output_folder: Some(dir.display().to_string()),
                        ..Default::default()
                    }),
                )
                .await
                .map_err(rq)?
                .into_handle()
                .ok_or_else(|| Error::msg("torrent: could not add torrent"))?;
            handle.wait_until_initialized().await.map_err(rq)?;
            let stats = handle.stats();
            if stats.progress_bytes != stats.total_bytes {
                let _ = self
                    .session
                    .delete(TorrentIdOrHash::Id(handle.id()), false)
                    .await;
                return Err(Error::msg(
                    "torrent: installed files do not match the torrent; not seeding",
                ));
            }
            self.session.unpause(&handle).await.map_err(rq)?;
            self.seeds
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .insert(game_id.to_string(), (handle, info_hash.to_string()));
            Ok(())
        }

        /// Stop seeding a game (before its files are changed or removed).
        pub async fn stop(&self, game_id: &str) {
            let removed = self
                .seeds
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .remove(game_id);
            if let Some((handle, _)) = removed {
                let _ = self
                    .session
                    .delete(TorrentIdOrHash::Id(handle.id()), false)
                    .await;
            }
        }

        pub fn status(&self) -> Vec<SeedStatus> {
            self.seeds
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .iter()
                .map(|(game_id, (handle, info_hash))| {
                    let stats = handle.stats();
                    SeedStatus {
                        game_id: game_id.clone(),
                        info_hash: info_hash.clone(),
                        uploaded_bytes: stats.uploaded_bytes,
                        total_bytes: stats.total_bytes,
                    }
                })
                .collect()
        }

        pub async fn shutdown(&self) {
            self.session.stop().await;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use gamedist_core::{
        manifest::{ChunkRef, FileEntry, Launch},
        torrent::{build_metainfo, TorrentFile},
        ChunkId,
    };

    const PIECE: u32 = 16 * 1024;

    fn fixture(dir: &Path) -> (Platform, Vec<u8>) {
        let contents: Vec<(&str, Vec<u8>)> = vec![
            (
                "game.bin",
                (0..40_000u32).map(|i| (i % 251) as u8).collect(),
            ),
            ("data/a.txt", b"hello".to_vec()),
            ("data/empty", vec![]),
        ];
        let mut hasher = PieceHasher::new(PIECE);
        let mut files = Vec::new();
        for (path, data) in &contents {
            let full = dir.join(path);
            std::fs::create_dir_all(full.parent().unwrap()).unwrap();
            std::fs::write(&full, data).unwrap();
            hasher.update(data);
            files.push(FileEntry {
                path: path.to_string(),
                size: data.len() as u64,
                mode: 0o644,
                chunks: if data.is_empty() {
                    vec![]
                } else {
                    vec![ChunkRef {
                        id: ChunkId::of(data),
                        size: data.len() as u64,
                    }]
                },
            });
        }
        let platform = Platform {
            launch: Launch {
                exe: "game.bin".into(),
                args: vec![],
                cwd: ".".into(),
            },
            total_size: files.iter().map(|f| f.size).sum(),
            files,
        };
        let torrent_files: Vec<TorrentFile> = platform
            .files
            .iter()
            .map(|f| TorrentFile {
                path: f.path.clone(),
                size: f.size,
            })
            .collect();
        let meta = build_metainfo(
            "files",
            &torrent_files,
            PIECE,
            hasher.finish(),
            &["http://tracker.invalid/announce".into()],
            &[],
            "",
        )
        .unwrap();
        (platform, meta.bytes)
    }

    #[test]
    fn accepts_matching_torrent_and_recomputes_pieces() {
        let tmp = tempfile::tempdir().unwrap();
        let (platform, bytes) = fixture(tmp.path());
        let check = check_metainfo(&bytes, &platform).unwrap();
        assert_eq!(check.piece_length, PIECE);
        assert_eq!(check.info_hash_hex().len(), 40);
        assert_eq!(
            tree_pieces(&platform, tmp.path(), PIECE).unwrap(),
            check.pieces
        );

        // A modified tree no longer matches.
        std::fs::write(tmp.path().join("data/a.txt"), b"HELLO").unwrap();
        assert_ne!(
            tree_pieces(&platform, tmp.path(), PIECE).unwrap(),
            check.pieces
        );
        // A short file is an error, not a silent mismatch.
        std::fs::write(tmp.path().join("data/a.txt"), b"x").unwrap();
        assert!(tree_pieces(&platform, tmp.path(), PIECE).is_err());
    }

    #[test]
    fn rejects_torrents_that_differ_from_the_manifest() {
        let tmp = tempfile::tempdir().unwrap();
        let (platform, bytes) = fixture(tmp.path());

        // Different file list.
        let mut other = platform.clone();
        other.files[1].path = "data/b.txt".into();
        assert!(check_metainfo(&bytes, &other).is_err());
        let mut other = platform.clone();
        other.files.pop();
        assert!(check_metainfo(&bytes, &other).is_err());
        let mut other = platform.clone();
        other.files[0].size += 1;
        other.total_size += 1;
        assert!(check_metainfo(&bytes, &other).is_err());

        // Tampered metainfo.
        type Dict = std::collections::BTreeMap<Vec<u8>, Bencode>;
        let edit = |f: &dyn Fn(&mut Dict)| {
            let Bencode::Dict(mut root) = Bencode::decode(&bytes).unwrap() else {
                panic!()
            };
            let Some(Bencode::Dict(info)) = root.get_mut(&b"info"[..]) else {
                panic!()
            };
            f(info);
            Bencode::Dict(root).encode()
        };
        let renamed = edit(&|info| {
            info.insert(b"name".to_vec(), Bencode::str("../../evil"));
        });
        assert!(check_metainfo(&renamed, &platform).is_err());
        let extra = edit(&|info| {
            info.insert(b"private".to_vec(), Bencode::Int(1));
        });
        assert!(check_metainfo(&extra, &platform).is_err());
        let traversal = edit(&|info| {
            let Some(Bencode::List(files)) = info.get_mut(&b"files"[..]) else {
                panic!()
            };
            let Bencode::Dict(first) = &mut files[0] else {
                panic!()
            };
            first.insert(
                b"path".to_vec(),
                Bencode::List(vec![Bencode::str(".."), Bencode::str("game.bin")]),
            );
        });
        assert!(check_metainfo(&traversal, &platform).is_err());
        let short = edit(&|info| {
            info.insert(b"pieces".to_vec(), Bencode::Bytes(vec![0; 20]));
        });
        assert!(check_metainfo(&short, &platform).is_err());
        assert!(check_metainfo(b"not bencode", &platform).is_err());
    }
}
